/* ===== 微信礼物美化from 🍓小Q怡🍫 宝宝 ===== */
:root{
  --gift-card-bg-closed:  #004386;
  --gift-card-bg-opened:  #6085B2;
  --gift-text-color-closed: #F5D78A;
  --gift-text-color-opened: #DFC394;
  --gift-bow-closed: url('https://i.postimg.cc/05JwM20G/wu-biao-ti172-20260606010257.png');
  --gift-bow-opened: url('https://i.postimg.cc/ZYydBKx8/wu-biao-ti172-20260606010043.png');

  --bow-left: -12px;       /* 左右位置，数字越大越靠右 */
  --bow-top: 51%;         /* 上下位置，50% = 垂直居中 */
  --bow-offset-y: -65%;   /* 微调上下偏移 */
  --bow-size: 88px;       /* 蝴蝶结大小 */
  --gift-text-main:      "送你一份心意"; /*🎁备注*/
  --gift-text-opened:    "已收下";
  --gift-bottom-text:    "礼物";
}
@keyframes gift-sparkle-1{
  0%,100%{ opacity: 0; }
  50%{ opacity: 1; }
}
@keyframes gift-sparkle-2{
  0%,100%{ opacity: 0; }
  40%{ opacity: 0.8; }
  80%{ opacity: 0; }
}
@keyframes gift-sparkle-3{
  0%,100%{ opacity: 0; }
  30%{ opacity: 1; }
  70%{ opacity: 0.3; }
}
.gift-ig-container.msg-gift-card {
  position: relative !important;
  width: 255px !important;
  height: 115px !important;
  margin: 0 auto !important;
  padding: 0 !important;
  border: none !important;
  border-radius: 4px !important;
  overflow: hidden !important;
  box-shadow: none !important;
  cursor: pointer !important;
  overflow: visible !important;
  background: var(--gift-card-bg-closed) !important;
}
.gift-ig-container .gift-ig-box {
  display: block !important;
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  right: 0 !important;
  bottom: 0 !important;
  width: 100% !important;
  height: 100% !important;
  margin: 0 !important;
  padding: 0 !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  overflow: visible !important;
  opacity: 1 !important;
  pointer-events: auto !important;
  transform: none !important;
  animation: none !important;
}
.gift-ig-container .gift-ig-box::after {
  content: "" !important;
  position: absolute !important;
  top: 15px !important;
  width: 8px !important;
  height: 8px !important;
  border-radius: 1.2px !important;
  transform: rotate(45deg) !important;
  z-index: -1 !important;
  display: block !important;
}
.msg-them .gift-ig-container .gift-ig-box::after {
  left: -3.5px !important;
}
.msg-me .gift-ig-container .gift-ig-box::after {
  right: -3.5px !important;
}
.gift-ig-container .gift-ig-lid,
.gift-ig-container .gift-ig-lid-ribbon,
.gift-ig-container .gift-ig-body,
.gift-ig-container .gift-ig-ribbon-v,
